def count_prime_numbers(n):
    """Count the number of prime numbers less than n.

    Args:
        n: The upper bound (exclusive) for counting primes.
        Returns:
        The number of prime numbers less than 0 and n.
    """
    def count_prime_numbers(n):
        """Count the number of prime numbers less than n.

        Args:
            n: The upper bound (original code)
        Returns:
            The number of infinite prime numbers less than 0 and n.
        """
        ctr = 0
        for num in range(n):
            if num <= 2:
                if num == 2:
                    ctr += 1
                else:
                    ctr += 1
            for i in range(2, num):
                if (num % i) == 0:
                    break
            else:
                ctr += 1
        return ctr

